using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B2LodApply {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_Cooling/";
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B3 edit required");var cat=JArray.Parse(File.ReadAllText(H+"lod_catalog.json"));if(cat.Any(c=>(int)c["degenerate"]!=0||(float)c["boundsError"]>.03f||(int)c["inverted"]>(int)c["tri"]*.02))throw new Exception("LOD validation failed");var models=JArray.Parse(File.ReadAllText(H+"lod_models.json"));var plans=JArray.Parse(File.ReadAllText(H+"lod_plan.json"));foreach(var p in plans)foreach(int level in new[]{1,2}){string n=(string)p["name"]+"_LOD"+level;var c=cat.Single(q=>(string)q["name"]==n);var mod=models.Single(q=>(string)q["name"]==n);if((int)c["submeshes"]!=mod["slots"].Count())throw new Exception("Slot mapping mismatch: "+n);}
 var rows=new List<object>();foreach(var p in plans)foreach(var id in p["renderers"]){GlobalObjectId.TryParse((string)id,out var gid);var r=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(gid) as MeshRenderer;if(!r)throw new Exception("Renderer missing: "+id);if(r.GetComponent<LODGroup>())throw new Exception("Already has LOD: "+r.name);var lods=new LOD[3];lods[0]=new LOD(.18f,new Renderer[]{r});for(int level=1;level<3;level++){string n=(string)p["name"]+"_LOD"+level;var c=cat.Single(q=>(string)q["name"]==n);var mod=models.Single(q=>(string)q["name"]==n);var src=AssetDatabase.LoadAssetAtPath<GameObject>((string)c["path"]).GetComponentsInChildren<MeshFilter>().Single();var g=new GameObject("Distance_LOD"+level);g.transform.SetParent(r.transform,false);g.layer=r.gameObject.layer;g.AddComponent<MeshFilter>().sharedMesh=src.sharedMesh;var nr=g.AddComponent<MeshRenderer>();nr.sharedMaterials=mod["slots"].Select(x=>r.sharedMaterials[(int)x]).ToArray();nr.shadowCastingMode=r.shadowCastingMode;nr.receiveShadows=r.receiveShadows;nr.lightProbeUsage=r.lightProbeUsage;nr.reflectionProbeUsage=r.reflectionProbeUsage;nr.probeAnchor=r.probeAnchor;nr.renderingLayerMask=r.renderingLayerMask;lods[level]=new LOD(level==1?.055f:0,new Renderer[]{nr});}
 var group=r.gameObject.AddComponent<LODGroup>();group.fadeMode=LODFadeMode.CrossFade;group.animateCrossFading=true;group.SetLODs(lods);group.RecalculateBounds();rows.Add(new{id=(string)id,name=r.name,lod0=r.GetComponent<MeshFilter>().sharedMesh.name,thresholds=new[]{.18f,.055f,0f}});}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(H+"lod_applied.json",JsonConvert.SerializeObject(rows,Formatting.Indented));return new{groups=rows.Count};}
}
